INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52053, 0, 0, 'What? You\'ve come to laugh at Zanzil, too? Not again! I\'ll make you pay!', 14, 0, 100, 0, 0, 24337, 'Zanzil - Aggro'),
(52053, 1, 0, '%s begins to resurrect a swarm of |cFFCC0000Zanzili Zombies|r!', 41, 0, 100, 0, 0, 0, 'Zanzil - Announce Zanzili Zombies'),
(52053, 2, 0, 'Rise up! Zanzil\'s elixir gives you life!', 14, 0, 100, 0, 0, 24352, 'Zanzil - Zanzili Zombies 1'),
(52053, 2, 1, 'Who needs friends? Zanzil just makes his own! ', 14, 0, 100, 0, 0, 24351, 'Zanzil - Zanzili Zombies 2'),
(52053, 3, 0, '%s fills the area with a |cFF33FF00toxic gas|r!', 41, 0, 100, 0, 0, 0, 'Zanzil to Zanzil - Announce Graveyard Gas'),
(52053, 3, 1, 'How does that taste?', 14, 0, 0, 0, 0, 24343, 'Zanzil - SAY_KILL 2'),
(52053, 3, 2, 'Oooh, pretty... Zanzil\'s got big plans for this one...', 14, 0, 0, 0, 0, 24344, 'Zanzil - SAY_KILL 3'),
(52053, 4, 0, 'Breathe deep, friends! Breathe it all in!', 14, 0, 100, 0, 0, 24341, 'Zanzil to Zanzil - Graveyard Gas'),
(52053, 4, 1, 'Go, little one! Fight them! KILL THEM!', 14, 0, 0, 0, 0, 24350, 'Zanzil - SAY_BERSERK 2'),
(52053, 5, 0, '%s begins to resurrect a |cFF3366CCZanzili Berserker|r!', 41, 0, 100, 0, 0, 0, 'Zanzil - Announce Zanzili Berserker'),
(52053, 5, 1, 'Rise up! Zanzil\'s elixir gives you life!', 14, 0, 0, 0, 0, 24352, 'Zanzil - SAY_TROLLS 2'),
(52053, 6, 0, 'Maybe you need someone bigger to play with!', 14, 0, 100, 0, 0, 24349, 'Zanzil - Zanzili Berserker 1'),
(52053, 6, 1, 'Go, little one! Fight them! KILL THEM!', 14, 0, 100, 0, 0, 24350, 'Zanzil - Zanzili Berserker 2'),
(52053, 7, 0, 'Don\'t worry. Zanzil won\'t leave you dead for long...', 14, 0, 100, 0, 0, 24342, 'Zanzil - Slay 1'),
(52053, 7, 1, 'How does that taste?', 14, 0, 100, 0, 0, 24343, 'Zanzil - Slay 2'),
(52053, 7, 2, 'Oooh, pretty... Zanzil\'s got big plans for this one...', 14, 0, 100, 0, 0, 24344, 'Zanzil - Slay 3'),
(52053, 8, 0, 'You\'ll all suffer for this! Zul\'Gurub is NOTHING without Zan... Zan...', 14, 0, 100, 0, 0, 24338, 'Zanzil - Death');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52054, 0, 0, '%s is chasing you. Run!', 42, 0, 100, 0, 0, 0, 'Zanzili Berserker - Whisper Pursuit'),
(52054, 1, 0, '%s is chasing $n.', 16, 0, 100, 0, 0, 0, 'Zanzili Berserker - Announce Pursuit');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52059, 0, 0, 'No. NO! Get out! Leave me here with the memory of my sister!', 14, 0, 100, 0, 0, 24269, 'High Priestess Kilnara - SAY_AGGRO'),
(52059, 1, 0, 'Feel me agony!', 14, 0, 100, 0, 0, 24284, 'High Priestess Kilnara - SAY_WAVE_OF_AGONY'),
(52059, 2, 0, 'What have you done? I can\'t... control... RRAAAARRRGHHH!', 14, 0, 100, 0, 0, 24286, 'High Priestess Kilnara - SAY_TRANSFROM_1'),
(52059, 2, 1, 'Share in my pain!', 14, 0, 0, 0, 0, 24276, 'Kilnara kill feral 02'),
(52059, 3, 0, 'Haaa ha ha haa!  Now, heathens... face the TRUE might of Bethekk!', 14, 0, 100, 0, 0, 24287, 'High Priestess Kilnara - SAY_TRANSFROM_2'),
(52059, 3, 1, 'I am sworn to protect this place!', 14, 0, 0, 0, 0, 24278, 'Kilnara kill 02'),
(52059, 4, 0, 'I told you to leave!', 14, 0, 100, 0, 0, 24277, 'High Priestess Kilnara - SAY_PLAYER_KILL'),
(52059, 5, 0, 'This body is useless!', 14, 0, 100, 0, 0, 24274, 'High Priestess Kilnara - SAY_DEATH'),
(52059, 6, 0, 'Haaa ha ha haa!  Now, heathens... face the TRUE might of Bethekk!', 14, 0, 0, 0, 0, 24287, 'Kilnara transform 02 feral');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52148, 0, 0, 'Meddlesome insects! Now you will feel my wrath!', 14, 0, 100, 0, 0, 24268, 'Jin\'do the Godbreaker - Intro'),
(52148, 1, 0, 'Welcome to de great show, friends. Just wait \'til ya see what I got in store for ya.', 14, 0, 100, 0, 0, 24254, 'Jin\'do the Godbreaker - Aggro'),
(52148, 2, 0, 'Jin\'do charges his weapon with the Shadows of Hakkar!', 41, 0, 100, 0, 0, 0, 'Jin\'do the Godbreaker - Announce Shadows of Hakkar'),
(52148, 2, 1, 'Ain\'t NO ONE gonna stop Jin\'do!', 14, 0, 0, 0, 0, 24257, 'Jindo kill 01 phase'),
(52148, 3, 0, 'Now, have a taste of Jin\'do\'s true powah!', 14, 0, 100, 0, 0, 24267, 'Jin\'do the Godbreaker - Phase 2 Intro'),
(52148, 3, 1, 'You nothing!', 14, 0, 0, 0, 0, 24259, 'Jindo kill 02 phase'),
(52148, 4, 0, 'Hey! Grats, mon!', 14, 0, 0, 0, 0, 24260, 'Jindo kill mandokir'),
(52148, 5, 0, 'Now, have a taste of Jin\'do\'s true powah!', 14, 0, 0, 0, 0, 24267, 'Jindo phase 2'),
(52148, 6, 0, 'Meddlesome insects! Now you will feel my wrath!', 14, 0, 0, 0, 0, 24268, 'Jindo spawn');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52155, 0, 0, 'You disssssturb the plans of Gurubashi, little one.  It\'sss too late for you.  Too late for all of you!', 14, 0, 100, 0, 0, 24326, 'High Priest Venoxis - Aggro'),
(52155, 1, 0, 'Yesss...ssssuccumb to the venom...', 14, 0, 100, 0, 0, 24320, 'High Priest Venoxis - Whispers of Hethiss'),
(52155, 2, 0, 'Let the coils of death unfurl!', 14, 0, 100, 0, 0, 24319, 'High Priest Venoxis - Blessing of the Snake God'),
(52155, 3, 0, 'Hisss word, FILLS me, MY BLOOD IS VENOM, AND YOU WILL BATHE IN THE GLORY OF THE SNAKE GOD!!!', 14, 0, 100, 0, 0, 24321, 'High Priest Venoxis - Say Bloodvenom'),
(52155, 4, 0, '|TInterface\\Icons\\ability_creature_poison_06.blp:20|t High Priest Venoxis begins casting |cFFFF0000|Hspell:96637|h[Bloodvenom]|h|r!', 41, 0, 100, 0, 0, 0, 'High Priest Venoxis - Announce Bloodvenom'),
(52155, 4, 1, 'Your sssacrifice pleases him.', 14, 0, 0, 0, 0, 24323, 'High Priest Venoxis - EMOTE_BLOODVENOM 2'),
(52155, 5, 0, 'High Priest Venoxis is exhausted!', 41, 0, 100, 0, 0, 0, 'High Priest Venoxis'),
(52155, 6, 0, 'The mortal coil unwindsss...', 41, 0, 100, 0, 0, 0, 'High Priest Venoxis - Slay 1'),
(52155, 6, 1, 'Your sssacrifice pleases him.', 41, 0, 100, 0, 0, 0, 'High Priest Venoxis - Slay 2'),
(52155, 7, 0, 'My death means...nothing...', 14, 0, 100, 0, 0, 24318, 'High Priest Venoxis - Death');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52222, 0, 0, 'Your deceit is unforgivable, Jin\'do. You spit in the face of a god!', 14, 0, 100, 0, 0, 24246, 'Spirit of Hakkar to Jin\'do the Godbreaker'),
(52222, 1, 0, 'You overstepped your bounds, Jin\'do. You toy with powers that are beyond you. Have you forgotten who I am? Have you forgotten what I can do?!', 14, 0, 100, 0, 0, 24244, 'Spirit of Hakkar to Jin\'do the Godbreaker'),
(52222, 2, 0, 'Your deceit is unforgivable, Jin\'do. You spit in the face of a god!', 14, 0, 0, 0, 0, 24246, 'Hakkar phase 2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52258, 0, 0, 'You seek me? We fight now!', 14, 0, 0, 0, 0, 24232, 'Gri\'lek - aggro'),
(52258, 1, 0, 'Gri\'lek wanders... no more...', 14, 0, 0, 0, 0, 24233, 'Gri\'lek - death'),
(52258, 2, 0, 'I COME FOR YOU, LITTLE MORTAL!', 14, 0, 0, 0, 0, 24234, 'Gri\'lek - fixate 1'),
(52258, 2, 1, 'I will catch you, small one!', 14, 0, 0, 0, 0, 24235, 'Gri\'lek - fixate 2'),
(52258, 3, 0, 'Crushed!', 14, 0, 0, 0, 0, 24236, 'Gri\'lek - kill 1'),
(52258, 3, 1, 'You are weak!', 14, 0, 0, 0, 0, 24237, 'Gri\'lek - kill 2'),
(52258, 4, 0, 'Coward! You cannot run!', 14, 0, 0, 0, 0, 24241, 'Gri\'lek - root 1'),
(52258, 4, 1, 'No! You do not escape the rage of the Gurubashi!', 14, 0, 0, 0, 0, 24242, 'Gri\'lek - root 2'),
(52258, 5, 0, '%s is chasing you. Run!', 42, 0, 0, 0, 0, 0, 'Gri\'lek - fixate announce');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52269, 0, 0, 'Feel the sting of a thousand cuts!', 14, 0, 0, 0, 0, 24307, 'Renataki - blades 1'),
(52269, 0, 1, 'One thousand blades!', 14, 0, 0, 0, 0, 24308, 'Renataki - blades 2'),
(52269, 1, 0, 'Ahhh... I shall add a new blade to my collection today...', 14, 0, 0, 0, 0, 24309, 'Renataki - aggro'),
(52269, 2, 0, 'Not even a thousand deaths could put my soul to rest...', 14, 0, 0, 0, 0, 24310, 'Renataki - death'),
(52269, 3, 0, 'A swift slice to the throat, and this one falls like any other.', 14, 0, 0, 0, 0, 24311, 'Renataki - kill 1'),
(52269, 3, 1, 'Learn your place.', 14, 0, 0, 0, 0, 24312, 'Renataki - kill 2'),
(52269, 4, 0, 'Perhaps a quick stab will let out all that tension in your shoulders...', 14, 0, 0, 0, 0, 24314, 'Renataki - mocking'),
(52269, 4, 1, 'Rogues do it from behind...', 14, 0, 0, 0, 0, 24315, 'Renataki - mocking'),
(52269, 4, 2, 'It only hurts this much the first time.  The second time, you\'re dead.', 14, 0, 0, 0, 0, 24316, 'Renataki - mocking');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52271, 0, 0, 'Today, you\'ll wish you never stirred from your bed!', 14, 0, 100, 0, 0, 24247, 'Hazza\'rah - Aggro'),
(52271, 1, 0, 'Let us see what horrors stir within your nightmares!', 14, 0, 100, 0, 0, 24249, 'Hazza\'rah to Hazza\'rah - Nightmare'),
(52271, 1, 1, 'Slumber... another dream awaits you...', 14, 0, 100, 0, 0, 24251, 'Hazza\'rah to Hazza\'rah - Nightmare'),
(52271, 2, 0, 'Let us see what horrors stir within your nightmares!', 14, 0, 0, 0, 0, 24249, 'Hazza\'rah - dreamstate 1'),
(52271, 2, 1, 'Let\'s see what\'s more horrifying... to dream unwaking, or to awaken in a living nightmare!', 14, 0, 0, 0, 0, 24250, 'Hazza\'rah - dreamstate 2'),
(52271, 2, 2, 'Slumber... another dream awaits you...', 14, 0, 0, 0, 0, 24251, 'Hazza\'rah - dreamstate 3'),
(52271, 3, 0, 'My spirit dreams no longer...', 14, 0, 100, 0, 0, 24248, 'Hazza\'rah - Death'),
(52271, 3, 1, 'There there... close your eyes...', 14, 0, 0, 0, 0, 24253, 'Hazza\'rah - kill 2'),
(52271, 4, 0, 'Attack the nightmare illusions and defend your sleeping allies!', 42, 0, 0, 0, 0, 0, 'Hazza\'rah - dreamstate announce');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52286, 0, 0, 'You shall regret disturbing my homeland!', 14, 0, 0, 0, 0, 24329, 'Wushoolay - aggro'),
(52286, 1, 0, 'The end of our empire... is only the beginning...', 14, 0, 0, 0, 0, 24330, 'Wushoolay - death'),
(52286, 2, 0, 'Shocking. I know.', 14, 0, 0, 0, 0, 24331, 'Wushoolay - kill 1'),
(52286, 2, 1, 'Feel the might of my storm!', 14, 0, 0, 0, 0, 24332, 'Wushoolay - kill 2'),
(52286, 3, 0, 'Can you feel that tingling sensation? It may be your last.', 14, 0, 0, 0, 0, 24333, 'Wushoolay - lightning nuke 1'),
(52286, 3, 1, 'You\'re in for a stunning surprise...', 14, 0, 0, 0, 0, 24334, 'Wushoolay - lightning nuke 2'),
(52286, 4, 0, 'Are you quicker than lightning?', 14, 0, 0, 0, 0, 24335, 'Wushoolay - lightning rush 1'),
(52286, 4, 1, 'In a flash, you\'ll be nothing more than dust...', 14, 0, 0, 0, 0, 24403, 'Wushoolay - lightning rush 2'),
(52286, 4, 2, 'The storm feeds my power!', 14, 0, 0, 0, 0, 24336, 'Wushoolay - lightning rush 3'),
(52286, 5, 0, '%s is about to blast you with lightning! Get away!', 42, 0, 0, 0, 0, 0, 'Wushoolay - emote - lightning nuke');
